import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val s = br.readLine()!!
    val solve = StringBuilder()
    var i = 0
    while (i < s.length) {
        if (i + 3 <= s.length && s.substring(i, i + 3) == "dot") {
            solve.append('.')
            i += 3
        } else if (i + 2 <= s.length && s.substring(i, i + 2) == "at") {
            solve.append('@')
            i += 2
        } else {
            solve.append(s[i])
            i++
        }
    }

    fun check(sb: StringBuilder) {
        if (sb.isNotEmpty()) {
            if (sb[0] == '.') {
                sb.deleteCharAt(0)
                sb.insert(0, "dot")
            } else if (sb[0] == '@') {
                sb.deleteCharAt(0)
                sb.insert(0, "at")
            }
            if (sb.isNotEmpty()) {
                val lastIdx = sb.length - 1
                if (sb[lastIdx] == '.') {
                    sb.deleteCharAt(lastIdx)
                    sb.append("dot")
                } else if (sb[lastIdx] == '@') {
                    sb.deleteCharAt(lastIdx)
                    sb.append("at")
                }
            }
        }
    }

    check(solve)
    val solveStr = solve.toString()
    val atCount = solveStr.count { it == '@' }
    if (atCount == 1) {
        println(solveStr)
    } else {
        val output = StringBuilder()
        var firstAt = true
        for (c in solveStr) {
            if (c == '@') {
                if (firstAt) {
                    output.append('@')
                    firstAt = false
                } else {
                    output.append("at")
                }
            } else {
                output.append(c)
            }
        }
        println(output)
    }
}

