fun main() {
    val s = readLine()!!
    val n = s.length
    val solveBuilder = StringBuilder()
    var i = 0
    while (i < n) {
        if (i + 3 <= n && s.substring(i, i + 3) == "dot") {
            solveBuilder.append('.')
            i += 3
        } else if (i + 2 <= n && s.substring(i, i + 2) == "at") {
            solveBuilder.append('@')
            i += 2
        } else {
            solveBuilder.append(s[i])
            i += 1
        }
    }
    var solve = solveBuilder.toString()

    if (solve.isNotEmpty()) {
        when (solve[0]) {
            '.' -> solve = "dot" + solve.substring(1)
            '@' -> solve = "at" + solve.substring(1)
        }
    }
    if (solve.isNotEmpty()) {
        val lastIndex = solve.length - 1
        when (solve[lastIndex]) {
            '.' -> solve = solve.substring(0, lastIndex) + "dot"
            '@' -> solve = solve.substring(0, lastIndex) + "at"
        }
    }

    val cont = solve.count { it == '@' }
    if (cont == 1) {
        println(solve)
    } else {
        var ok = true
        val output = StringBuilder()
        for (c in solve) {
            if (c == '@') {
                if (ok) {
                    output.append('@')
                    ok = false
                } else {
                    output.append("at")
                }
            } else {
                output.append(c)
            }
        }
        println(output.toString())
    }
}

